'use strict';
/* CYBER STUDY: オフラインで動作する学習用SPA。保存はlocalStorageのみ。 */
const $=id=>document.getElementById(id);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='cyber-study-state-v1'; // v1データを引き継ぐ
const initial={cards:{},exam:{},lessons:{},notes:[],history:[],sqlSolved:{},dojoSolved:{},settings:{name:'STUDENT'}};
function readState(){try{let o=JSON.parse(localStorage.getItem(KEY));if(o&&typeof o==='object'&&!Array.isArray(o))return {...structuredClone(initial),...o};}catch(e){console.warn(e)}return structuredClone(initial)}
let state=readState();
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){toast('保存できません。ブラウザの保存設定を確認してください');return false}}
let toastTimer;function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function logActivity(type,label){state.history.unshift({type,label,at:new Date().toISOString()});state.history=state.history.slice(0,150);persist()}
