function renderVisualGuide(l){const v=VISUAL_GUIDES[l.id];if(!v)return '';return `<div class="visual-guide"><div class="vg-goal"><strong>✓ この授業でできるようになること</strong><p>${escapeHTML(v.goal)}</p></div><h3>① 図で流れをつかむ</h3><div class="vg-steps">${v.steps.map((x,i)=>`<div class="vg-step"><small>STEP ${i+1}</small><strong>${escapeHTML(x[0])}</strong><span>${escapeHTML(x[1])}</span></div>`).join('')}</div><h3>② 操作して理解する</h3><div class="vg-lab"><strong>${escapeHTML(v.tryTitle)}</strong><p>${escapeHTML(v.tryHelp)}</p>${v.kind==='cpu'?`<label>命令数 <input id="vgWork" type="range" min="100" max="1000" step="100" value="500"></label><label>処理能力（命令/秒） <input id="vgRate" type="range" min="100" max="500" step="100" value="200"></label><output id="vgResult"></output>`:v.kind==='os'?`<label>アプリA（MB） <input id="vgWork" type="range" min="100" max="900" step="100" value="400"></label><label>アプリB（MB） <input id="vgRate" type="range" min="100" max="900" step="100" value="300"></label><output id="vgResult"></output>`:`<div class="vg-bits">${[16,8,4,2,1].map((n,i)=>`<button type="button" class="vg-bit" data-bit="${n}" aria-pressed="false"><small>${n}</small><b>0</b></button>`).join('')}</div><output id="vgResult">00000₂ = 0₁₀</output>`}</div><h3>③ 解説と練習問題で定着</h3><p class="muted tiny">下にある従来の図解・解説・確認問題・ステップアップ練習もそのまま利用できます。</p></div>`}
