function renderExam(){let answeredCount=questions.filter(q=>state.exam[q.id]).length,correct=questions.filter(q=>state.exam[q.id]?.correct).length;return pageHeader('EXAM SIMULATOR','応用情報 問題演習','科目Aの基礎知識を4択で練習。オリジナル問題を分野別に演習。')+`<div class="stats"><div class="stat"><span>QUESTIONS</span><strong>${questions.length}</strong></div><div class="stat"><span>ANSWERED</span><strong>${answeredCount}</strong></div><div class="stat"><span>ACCURACY（最新回答）</span><strong>${answeredCount?Math.round(correct/answeredCount*100):0}<em>%</em></strong></div><div class="stat"><span>WEAK</span><strong>${questions.filter(q=>state.exam[q.id]&&!state.exam[q.id].correct).length}</strong></div></div><section class="panel"><div class="flex space"><div class="flex"><label class="field">分野<select id="examCategory" class="select"><option value="all">すべての分野</option>${[...new Set(questions.map(q=>q.category))].map(x=>`<option>${escapeHTML(x)}</option>`).join('')}</select></label><label class="field">出題<select id="examMode" class="select"><option value="all">全問題</option><option value="weak">苦手のみ</option><option value="new">未解答のみ</option></select></label></div><button class="btn primary" id="examStart">▶ 演習を開始</button></div></section><section class="panel" style="margin-top:18px"><div class="flex space"><span class="kicker" id="examCount">READY</span><span class="pill" id="examCategoryTag">AP / ORIGINAL</span></div><div class="progress" style="margin:18px 0"><div id="examProgress" style="width:0%"></div></div><h2 id="examQuestion" style="line-height:1.8">「演習を開始」を押してね。</h2><div id="examChoices"></div><div id="examFeedback" aria-live="polite"></div><div class="flex" style="margin-top:20px"><button class="btn primary" id="examNext" disabled>次の問題 →</button><span class="helper">※ IPA公式過去問ではありません。</span></div></section>`}
function bindExam(){const start=()=>{const cat=$('examCategory').value,mode=$('examMode').value;examPool=questions.filter(q=>(cat==='all'||q.category===cat)&&(mode==='all'||(mode==='weak'?state.exam[q.id]&&!state.exam[q.id].correct:!state.exam[q.id])));examIndex=0;showExam()};$('examStart').onclick=start;$('examNext').onclick=()=>{examIndex++;showExam()};start()}
function showExam(){examAnswered=false;$('examFeedback').innerHTML='';$('examNext').disabled=true;$('examChoices').innerHTML='';let n=examPool.length;if(!n||examIndex>=n){$('examCount').textContent=n?'COMPLETE':'NO QUESTIONS';$('examQuestion').textContent=n?'演習終了！ 苦手問題を復習しよう。':'条件に合う問題がありません。';$('examCategoryTag').textContent='AP / ORIGINAL';$('examProgress').style.width=n?'100%':'0%';return}let q=examPool[examIndex];$('examCount').textContent=`QUESTION ${examIndex+1} / ${n}`;$('examCategoryTag').textContent=q.category;$('examQuestion').textContent=q.question;$('examProgress').style.width=`${examIndex/n*100}%`;$('examChoices').innerHTML=q.choices.map((x,i)=>`<button class="choice" data-choice="${i}">${'ABCD'[i]}. ${escapeHTML(x)}</button>`).join('');document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(examAnswered)return;examAnswered=true;let v=+b.dataset.choice,ok=v===q.answer;state.exam[q.id]={correct:ok,selected:v,at:new Date().toISOString()};persist();logActivity('exam',`問題${q.id} ${ok?'正解':'不正解'}：${q.category}`);document.querySelectorAll('[data-choice]').forEach(x=>{x.disabled=true;if(+x.dataset.choice===q.answer)x.classList.add('correct');else if(x===b)x.classList.add('wrong')});$('examFeedback').innerHTML=`<div class="answer"><b>${ok?'✓ 正解！':'✕ 不正解。正解は'+ 'ABCD'[q.answer]+'です。'}</b><br><br>${escapeHTML(q.explanation)}</div>`;$('examNext').disabled=false})}
/* SQL道場は教育用の限定SQLサブセット。任意のSQLやDDL/DMLは実行しない。 */
function renderSQL(){if(sqlTab==='db')return renderDBLab();const m=SQL_MISSIONS[sqlMission];return pageHeader('QUERY TERMINAL','SQL道場',`${SQL_MISSIONS.length}問のSQL演習。JOIN・CASE・ウィンドウ関数・CTEまでSQLiteで実行。入力欄は空欄から開始。`)+`<div class="flex" style="margin-bottom:16px"><button class="btn ${sqlTab==='mission'?'primary':''}" data-sqltab="mission">図解・体験モード</button><button class="btn ${sqlTab==='free'?'primary':''}" data-sqltab="free">自由SQL演習モード</button><button class="btn" data-sqltab="db">DB設計・更新30問</button></div><div class="two-col"><section class="panel"><div class="flex space"><span class="kicker">SQL EDITOR // ${sqlTab.toUpperCase()}</span><span class="pill">SQLITE ENGINE / FALLBACK</span></div>${sqlTab==='mission'?`<label class="field" style="margin:15px 0">ミッション<select class="select" id="missionSelect">${SQL_MISSIONS.map((x,i)=>`<option value="${i}" ${i===sqlMission?'selected':''}>${String(i+1).padStart(3,'0')} [${x.category}] ${x.title}${state.sqlSolved[i]?' ✓':''}</option>`).join('')}</select></label><p class="sub" style="margin-bottom:15px">${escapeHTML(m.desc)}</p>`:'<p class="sub" style="margin:15px 0">SQLite接続時はSELECT・JOIN・GROUP BY・HAVING・サブクエリ・CASE・ウィンドウ関数・WITH句を利用できます。SQLiteが使えない場合は基礎演習用の限定エンジンです。</p>'}<textarea class="sql-editor" id="sqlEditor" spellcheck="false" placeholder="ここに自分でSQLを書こう！\n例：SELECT ... FROM ...;" aria-label="SQLを入力"></textarea><div class="flex" style="margin-top:14px"><button class="btn primary" id="runSQL">▶ RUN QUERY</button><button class="btn" id="resetSQL">↻ リセット</button><button class="btn" id="hintSQL">? ヒント（段階式）</button><button class="btn" id="answerSQL">◈ 模範SQLを見る</button><button class="btn" id="nextSQL">次のミッション →</button></div><div id="sqlHint" class="helper" style="margin-top:12px"></div></section><section class="panel"><div class="panel-head"><h2>▤ TABLE DATA</h2><span class="pill">READ ONLY</span></div><h3>customers</h3>${htmlTable(CUSTOMERS)}<h3 style="margin-top:22px">orders</h3>${htmlTable(ORDERS)}<p class="helper" style="margin-top:14px">注文のない顧客も含まれます。LEFT JOINでは対応がない注文列はNULLになります。</p></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h2>◈ EXECUTION RESULT</h2><span id="sqlStatus" class="pill">WAITING</span></div><div id="sqlResult" class="table-scroll"><div class="empty">SQLを入力して RUN QUERY を押してください。</div></div></section>`}
function htmlTable(rows){if(!rows.length)return '<div class="empty">0 rows</div>';let keys=Object.keys(rows[0]);return `<div class="table-scroll"><table class="data-table"><thead><tr>${keys.map(k=>`<th>${escapeHTML(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${r[k]===null?'<span class="muted">NULL</span>':escapeHTML(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function bindSQL(){if(sqlTab==='db')return bindDBLab();
  // モードや課題の切替時は新しい空欄で開始する。
  document.querySelectorAll('[data-sqltab]').forEach(b=>b.onclick=()=>{sqlTab=b.dataset.sqltab;sqlHintStep=0;navigate('sql')});
  $('missionSelect')?.addEventListener('change',e=>{sqlMission=+e.target.value;sqlHintStep=0;navigate('sql')});
  $('nextSQL').onclick=()=>{sqlMission=(sqlMission+1)%SQL_MISSIONS.length;sqlHintStep=0;navigate('sql')};
  $('resetSQL').onclick=()=>{$('sqlEditor').value='';$('sqlHint').textContent='入力欄を空にしました。最初から考えてみよう。';sqlHintStep=0;$('sqlResult').innerHTML='<div class="empty">SQLを入力して RUN QUERY を押してください。</div>';$('sqlStatus').textContent='WAITING';$('sqlEditor').focus()};
  $('hintSQL').onclick=()=>{
    const m=SQL_MISSIONS[sqlMission];sqlHintStep=Math.min(sqlHintStep+1,3);
    $('sqlHint').textContent='ヒント'+sqlHintStep+'：'+m.hints[sqlHintStep-1]+'（3段階まで表示）';
  };
  $('answerSQL').onclick=()=>{
    const m=SQL_MISSIONS[sqlMission];
    $('sqlHint').textContent='模範SQL（自動入力はしません）：\n'+m.sql+'\n\n内容を理解して、自分で入力してみよう。';
    sqlHintStep=3;
  };
  $('runSQL').onclick=async()=>{
    const query=$('sqlEditor').value.trim();
    if(!query){$('sqlStatus').textContent='INPUT REQUIRED';$('sqlResult').innerHTML='<div class="answer">SQLが未入力です。自分でSQLを書いてみよう。</div>';$('sqlEditor').focus();return}
    try{
      const rows=await executeSQL33(query);
      $('sqlResult').innerHTML=htmlTable(rows)+`<p class="helper">${rows.length} row(s) returned</p>`;
      $('sqlStatus').textContent='SUCCESS';
      if(sqlTab==='mission'){
        if(await missionPass33(query,rows,SQL_MISSIONS[sqlMission].test)){
          if(!state.sqlSolved[sqlMission]){state.sqlSolved[sqlMission]=true;logActivity('sql',`SQLミッション${sqlMission+1}をクリア`)}
          $('sqlStatus').textContent='✓ MISSION CLEAR';toast('SQLミッションクリア！')
        }else{
          $('sqlStatus').textContent='NOT YET';
          $('sqlResult').insertAdjacentHTML('beforeend','<div class="answer">SQLは実行できたけれど、今回のミッションの条件をまだ満たしていないよ。課題文を確認しよう。</div>')
        }
      }
    }catch(e){$('sqlResult').innerHTML=`<div class="answer" style="border-color:var(--red)">${escapeHTML(e.message)}</div>`;$('sqlStatus').textContent='QUERY ERROR'}
  };
}


// ===== SQLite実行エンジン（sql.js 1.10.3 / CDN） =====
// 初回にネット接続が必要。外部サーバーにSQLは送信せず、SQLiteはブラウザ内で実行。
const SQLITE_CDN33='https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/';
let sqliteDb33=null,sqlitePromise33=null;
function loadSQLite33(){
 if(sqliteDb33)return Promise.resolve(sqliteDb33);
 if(sqlitePromise33)return sqlitePromise33;
 sqlitePromise33=new Promise((resolve,reject)=>{
   if(typeof initSqlJs==='function'){resolve();return;}
   const script=document.createElement('script');script.src=SQLITE_CDN33+'sql-wasm.js';
   script.onload=resolve;script.onerror=()=>reject(Error('SQLiteライブラリを取得できません。インターネット接続を確認してください。'));
   document.head.appendChild(script);
 }).then(()=>initSqlJs({locateFile:file=>SQLITE_CDN33+file})).then(SQL=>{
   const db=new SQL.Database();
   db.run('CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL)');
   db.run('CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER, product TEXT)');
   const c=db.prepare('INSERT INTO customers (id,name) VALUES (?,?)');
   CUSTOMERS.forEach(r=>c.run([r.id,r.name]));c.free();
   const o=db.prepare('INSERT INTO orders (id,customer_id,product) VALUES (?,?,?)');
   ORDERS.forEach(r=>o.run([r.id,r.customer_id,r.product]));o.free();
   sqliteDb33=db;return db;
 }).catch(e=>{sqlitePromise33=null;throw e});
 return sqlitePromise33;
}
function safeReadSQL33(sql){
 const clean=sql.trim().replace(/;\s*$/,'');
 // 参照系のみ。複数文、コメント、PRAGMA、更新・DDLは禁止。
 if(!/^(SELECT|WITH)\s/i.test(clean)||/;|--|\/\*|\*\//.test(clean)||/\b(INSERT|UPDATE|DELETE|DROP|ALTER|CREATE|ATTACH|DETACH|PRAGMA|REPLACE|VACUUM|REINDEX|ANALYZE|TRIGGER|LOAD_EXTENSION)\b/i.test(clean))throw Error('SELECT / WITH の読み取り専用SQLを1文だけ入力してください。');
 return clean;
}
async function executeSQL33(query){
 const sql=safeReadSQL33(query);
 try{
   const db=await loadSQLite33();
   const result=db.exec(sql);
   if(!result.length)return [];
   const r=result[0];
   return r.values.map(values=>Object.fromEntries(r.columns.map((key,i)=>[key,values[i]])));
 }catch(e){
   // SQLite未取得時は従来の限定SQLエンジンで基礎問題を継続可能。
   if(!sqliteDb33){
     try{return executeStudySQL(query)}catch(_){throw Error('SQLiteを読み込めません。高度なSQL演習にはインターネット接続が必要です。詳細：'+e.message)}
   }
   throw e;
 }
}
async function missionPass33(query,rows,test){
 const mission=SQL_MISSIONS[sqlMission];
 const required={"join-advanced":/\bjoin\b/i,case:/\bcase\b/i,window:/\bover\s*\(/i,cte:/^\s*with\b/i,group:/\bgroup\s+by\b/i,having:/\bhaving\b/i,subquery:/\b(select|with)\b[\s\S]*\bselect\b/i};
 if(required[test]&&!required[test].test(query))return false;
 if(!required[test]){
   // 既存100問の判定ルールを維持
   if(!sqliteDb33)return missionPass(query,rows,test);
   const actual=query.toLowerCase().replace(/\s+/g,' ');
   const clauses={basic:[],projection:[],where:['where'],order:['order by'],'where-order':['where','order by'],inner:['inner join',' on '],left:['left join',' on '],combined:[' join ',' on ','where','order by']}[test]||[];
   if(!clauses.every(x=>actual.includes(x)))return false;
 }
 const expected=await executeSQL33(mission.sql);
 return JSON.stringify(rows)===JSON.stringify(expected);
}

function missionPass(query,rows,test){
 const m=SQL_MISSIONS[sqlMission];
 const actual=query.toLowerCase().replace(/\s+/g,' ');
 const required={basic:[],projection:[],where:['where'],order:['order by'], 'where-order':['where','order by'],inner:['inner join',' on '],left:['left join',' on '],combined:[' join ',' on ','where','order by']}[test]||[];
 if(!required.every(x=>actual.includes(x)))return false;
 // 期待する列、値、並び順を照合。空の結果だけで正解にならないようにする。
 const expected=executeStudySQL(m.sql);
 return JSON.stringify(rows)===JSON.stringify(expected);
}
function executeStudySQL(query){let q=query.trim().replace(/;\s*$/,'').replace(/\s+/g,' ');if(!/^select\s/i.test(q))throw Error('この学習用エンジンはSELECT文のみ対応しています。');if(/\b(insert|update|delete|drop|alter|create|union|into|having|limit|group\s+by)\b/i.test(q))throw Error('未対応のSQL構文です。SELECT / WHERE / JOIN / ORDER BYを使ってください。');let match=q.match(/^select\s+(.+?)\s+from\s+(customers|orders)(?:\s+(?:as\s+)?(?!inner\b|left\b|where\b|order\b)([a-z]\w*))?(?:\s+(inner|left)(?:\s+outer)?\s+join\s+(customers|orders)(?:\s+(?:as\s+)?(?!on\b)([a-z]\w*))?\s+on\s+([\w.]+)\s*=\s*([\w.]+))?(?:\s+where\s+([\w.]+)\s*=\s*(\d+|'[^']*'))?(?:\s+order\s+by\s+([\w.]+)(?:\s+(asc|desc))?)?$/i);if(!match)throw Error('SQL構文を解釈できません。例：SELECT * FROM customers; または JOIN / WHERE / ORDER BY を試してください。');let [,fields,base,baseAlias,joinType,other,otherAlias,leftCol,rightCol,whereCol,whereVal,orderCol,orderDir]=match;base=base.toLowerCase();baseAlias=baseAlias||base;otherAlias=otherAlias||other;const tables={customers:CUSTOMERS,orders:ORDERS};function fieldValue(row,key){let parts=key.split('.');if(parts.length===2){let alias=parts[0];if(alias!==baseAlias&&alias!==base&&alias!==otherAlias&&alias!==other)throw Error('不明なテーブル別名：'+alias);return row[alias+'.'+parts[1]]}if(parts.length!==1)throw Error('不明な列：'+key);let values=Object.entries(row).filter(([k])=>k.endsWith('.'+key));if(!values.length)throw Error('不明な列：'+key);if(values.length>1)throw Error('同名の列があります。テーブル別名を指定してください：'+key);return values[0][1]}
function qualify(obj,alias,table){let out={};Object.entries(obj).forEach(([k,v])=>{out[alias+'.'+k]=v;out[table+'.'+k]=v});return out}let rows=tables[base].map(x=>qualify(x,baseAlias,base));if(joinType){if(other.toLowerCase()===base)throw Error('この教材では同じ表同士のJOINには未対応です。');let result=[];for(let r of rows){let matches=0;for(let o of tables[other.toLowerCase()]){let combined={...r,...qualify(o,otherAlias,other)};if(fieldValue(combined,leftCol)===fieldValue(combined,rightCol)){result.push(combined);matches++}}if(!matches&&joinType.toLowerCase()==='left'){let nulls=Object.fromEntries(Object.keys(tables[other.toLowerCase()][0]).flatMap(k=>[[otherAlias+'.'+k,null],[other+'.'+k,null]]));result.push({...r,...nulls})}}rows=result}
if(whereCol){let val=whereVal.startsWith("'")?whereVal.slice(1,-1):Number(whereVal);rows=rows.filter(r=>fieldValue(r,whereCol)===val)}if(orderCol){rows.sort((a,b)=>{let x=fieldValue(a,orderCol),y=fieldValue(b,orderCol);return (x===null?-1:y===null?1:typeof x==='number'?x-y:String(x).localeCompare(String(y)))*(orderDir?.toLowerCase()==='desc'?-1:1)})}
let selections=fields.trim()==='*'?Object.keys(tables[base][0]).map(k=>baseAlias+'.'+k).concat(joinType?Object.keys(tables[other.toLowerCase()][0]).map(k=>otherAlias+'.'+k):[]):fields.split(',').map(s=>s.trim());if(!selections.length)throw Error('取得する列を指定してください。');return rows.map(r=>{let out={};selections.forEach(col=>{if(!/^[a-z_]\w*(?:\.[a-z_]\w*)?$/i.test(col))throw Error('列指定に対応していません：'+col);let label=col.split('.').pop();if(label in out)label=col;out[label]=fieldValue(r,col)});return out})}
