function dojoPool(){return DOJO_TASKS.map((t,i)=>({...t,id:i})).filter(t=>dojoGroup==='all'||t.group===dojoGroup)}
function renderDojo(){const pool=dojoPool(),t=pool[Math.min(dojoIndex,pool.length-1)];const solved=Object.values(state.dojoSolved||{}).filter(Boolean).length;return pageHeader('ENGINEER TRAINING','⚡ エンジニア道場','Git・Linux・正規表現を実務の場面で学ぶ。コマンドは実行せず、知識を判定します。')+`<div class="stats"><div class="stat"><span>DRILLS</span><strong>${DOJO_TASKS.length}</strong></div><div class="stat"><span>CLEARED</span><strong>${solved}</strong></div></div><section class="panel"><label class="field">分野<select class="select" id="dojoGroup">${[['all','すべて'],['Git','Git'],['Linux','Linux'],['正規表現','正規表現']].map(([v,n])=>`<option value="${v}" ${dojoGroup===v?'selected':''}>${n}</option>`).join('')}</select></label><div class="flex space" style="margin-top:20px"><span class="pill">${dojoIndex+1} / ${pool.length}</span><span class="pill">${escapeHTML(t.group)}</span></div><h2>${escapeHTML(t.title)}</h2><p class="sub">${escapeHTML(t.q)}</p><div id="dojoChoices">${t.choices.map((c,i)=>`<button class="choice" data-dojo-answer="${i}">${'ABC'[i]}. ${escapeHTML(c)}</button>`).join('')}</div><div id="dojoFeedback" aria-live="polite"></div><div class="flex" style="margin-top:20px"><button class="btn" id="dojoPrev" ${dojoIndex===0?'disabled':''}>← 前へ</button><button class="btn primary" id="dojoNext">次へ →</button></div></section><section class="panel"><h2>◈ 参考教材</h2><p class="sub">外部サイトの文章や問題は複製していません。学習項目を参考に独自作成しています。</p><a href="https://aidev-lab.org/#categories" target="_blank" rel="noopener noreferrer">AI Dev Lab ↗</a></section>`}
function bindDojo(){dojoAnswered=false;$('dojoGroup').onchange=e=>{dojoGroup=e.target.value;dojoIndex=0;navigate('dojo')};$('dojoPrev').onclick=()=>{dojoIndex=Math.max(0,dojoIndex-1);navigate('dojo')};$('dojoNext').onclick=()=>{dojoIndex=(dojoIndex+1)%dojoPool().length;navigate('dojo')};document.querySelectorAll('[data-dojo-answer]').forEach(b=>b.onclick=()=>{if(dojoAnswered)return;dojoAnswered=true;const t=dojoPool()[dojoIndex],selected=Number(b.dataset.dojoAnswer),correct=selected===t.answer;$('dojoFeedback').innerHTML=`<div class="note"><b>${correct?'✓ 正解！':'もう一度復習しよう。正解：'+ 'ABC'[t.answer]}</b><br>${escapeHTML(t.why)}</div>`;document.querySelectorAll('[data-dojo-answer]').forEach(x=>{x.disabled=true;if(+x.dataset.dojoAnswer===t.answer)x.classList.add('correct');else if(+x.dataset.dojoAnswer===selected)x.classList.add('incorrect')});if(correct){state.dojoSolved[t.id]=true;logActivity('dojo',t.group+'：'+t.title)}})}


const MODULE_PROGRESS_KEYS=['cyber-phantom-progress-v1','cyber-security-academy-v1','cyber-terminal-dojo-v1','cyber-incident-progress-v1'];
function collectModuleProgress(){const out={};for(const k of MODULE_PROGRESS_KEYS){try{const v=localStorage.getItem(k);if(v!==null)out[k]=JSON.parse(v)}catch(e){console.warn('backup skip',k,e)}}return out}
function restoreModuleProgress(o){for(const k of MODULE_PROGRESS_KEYS){try{if(Object.hasOwn(o,k))localStorage.setItem(k,JSON.stringify(o[k]));else localStorage.removeItem(k)}catch(e){console.warn('restore failed',k,e)}}}

