/* Web障害演習：仮想ログとコマンドのみ。実サーバーには一切接続しない。 */
const INCIDENT_SCENARIOS=[
 {title:'環境変数名のタイプミス',level:'初級',story:'デプロイ後、商品APIが起動できずHTTP 503を返している。まず環境変数を調べよう。',logs:'[09:01:03] INFO booting product-api\n[09:01:04] ERROR Required environment variable API_URL is missing\n[09:01:04] WARN readiness check failed (503)',tasks:[{prompt:'設定ファイルに記載されたAPIの変数名を確認しよう。',commands:['cat .env','grep API .env'],output:'API_ULR=https://api.training.local\n# API_URL の綴りと一致していません',why:'API_URL が必要なのに API_ULR と誤記されています。'},{prompt:'原因が分かったら、安全な復旧操作を選ぼう。',commands:['fix env API_ULR API_URL'],output:'✓ .envの変数名を修正しました（仮想環境）\n✓ アプリの再起動・ヘルスチェック: 200 OK',why:'設定値の誤字を直し、再起動後にヘルスチェックで復旧を確認します。'}]},
 {title:'DB接続プール枯渇',level:'中級',story:'アクセス集中後、Webの応答が遅くなり、500エラーが増えた。',logs:'[14:31:10] WARN request took 12000ms\n[14:31:12] ERROR Timeout waiting for connection from pool\n[14:31:13] ERROR HTTP 500 GET /orders',tasks:[{prompt:'アプリの直近ログからエラーを確認しよう。',commands:['tail -n 30 logs/app.log','grep ERROR logs/app.log'],output:'ERROR Timeout waiting for connection from pool\nactive=20 idle=0 waiting=43',why:'接続プールに空きがなく、DB接続を待つリクエストが滞留しています。'},{prompt:'応急対応後、恒久対策につなげる操作を選ぼう。',commands:['review pool'],output:'✓ 長時間トランザクションと接続リークを調査\n✓ 適切なタイムアウトとプール設定を見直す計画を作成',why:'単純な接続数の増加だけではなく、接続リーク・遅いクエリ・負荷を確認します。'}]},
 {title:'リバースプロキシの502',level:'中級',story:'サイトの入口は動いているが、プロキシから502 Bad Gatewayが返る。',logs:'[16:08:01] nginx ERROR connect() failed (111: Connection refused)\nupstream: http://127.0.0.1:8080/health\nGET / 502',tasks:[{prompt:'バックエンドの待受ポートを確認しよう。',commands:['ss -ltn','check upstream'],output:'LISTEN 127.0.0.1:8081\nnginx upstream = 127.0.0.1:8080',why:'アプリは8081で待受、プロキシは8080を参照しています。'},{prompt:'設定不一致を直して疎通を確認しよう。',commands:['fix upstream 8081'],output:'✓ nginx upstream -> 127.0.0.1:8081\n✓ 設定検証 OK / 仮想ヘルスチェック 200 OK',why:'正しい接続先を設定し、設定検証とエンドツーエンドの疎通を確認します。'}]}
];
let incidentIndex=0,incidentStep=0,incidentLines=[];
function incidentProgress(){try{return JSON.parse(localStorage.getItem('cyber-incident-progress-v1')||'{}')}catch{return {}}}
function renderIncident(){const s=INCIDENT_SCENARIOS[incidentIndex],progress=incidentProgress(),cleared=Object.keys(progress).filter(k=>progress[k]).length;return pageHeader('INCIDENT // SANDBOX','Web障害対応シミュレーター','架空のログを読み、仮想コマンドを入力して原因調査・復旧を練習します。実際のOSやサーバーには接続しません。')+`<div class="stats"><div class="stat"><span>SCENARIOS</span><strong>${INCIDENT_SCENARIOS.length}</strong></div><div class="stat"><span>CLEARED</span><strong>${cleared}</strong></div><div class="stat"><span>CURRENT STEP</span><strong>${Math.min(incidentStep+1,s.tasks.length)}<em> / ${s.tasks.length}</em></strong></div><div class="stat"><span>ENVIRONMENT</span><strong style="font-size:21px">SIMULATED</strong></div></div><div class="two-col"><section class="panel"><label class="field">障害シナリオ<select class="select" id="incidentSelect">${INCIDENT_SCENARIOS.map((x,i)=>`<option value="${i}" ${i===incidentIndex?'selected':''}>${i+1}. ${escapeHTML(x.title)}${progress[i]?' ✓':''}</option>`).join('')}</select></label><h2 style="margin-top:20px">${escapeHTML(s.title)} <span class="pill">${escapeHTML(s.level)}</span></h2><p class="sub">${escapeHTML(s.story)}</p><h3 style="margin-top:20px">障害ログ</h3><pre class="incident-log">${escapeHTML(s.logs)}</pre><h3>今の課題</h3><p class="sub" id="incidentTask">${incidentStep<s.tasks.length?escapeHTML(s.tasks[incidentStep].prompt):'✓ この障害を解決しました。別のシナリオに挑戦！'}</p><details style="margin-top:16px"><summary>ヒント・コマンド候補</summary><p class="helper">${incidentStep<s.tasks.length?s.tasks[incidentStep].commands.map(escapeHTML).join(' / '):'クリア済み'}</p></details></section><section class="panel"><h2>⌨ 仮想調査ターミナル</h2><p class="helper">コマンドはこのページ内だけで判定します。実際のPCでは実行されません。</p><pre id="incidentOutput" class="incident-log terminal-output">${escapeHTML(incidentLines.join('\n')||'TRAINING NODE READY\nコマンドを入力して Enter または「実行」を押してください。')}</pre><form id="incidentForm" class="flex" autocomplete="off"><label class="field" style="flex:1">training@incident:~$<input id="incidentInput" class="input" style="width:100%" placeholder="例：cat .env" ${incidentStep>=s.tasks.length?'disabled':''}></label><button class="btn primary" type="submit" ${incidentStep>=s.tasks.length?'disabled':''}>実行 ↵</button></form><div id="incidentFeedback" class="answer" aria-live="polite" style="display:none"></div><button class="btn" id="incidentReset" style="margin-top:16px">↻ このシナリオを最初から</button></section></div>`}
function bindIncident(){const $select=$('incidentSelect');$select.onchange=e=>{incidentIndex=+e.target.value;incidentStep=0;incidentLines=[];navigate('incident')};$('incidentReset').onclick=()=>{incidentStep=0;incidentLines=[];navigate('incident')};$('incidentForm').onsubmit=e=>{e.preventDefault();const raw=$('incidentInput').value.trim(),s=INCIDENT_SCENARIOS[incidentIndex],task=s.tasks[incidentStep];if(!raw||!task)return;incidentLines.push('training@incident:~$ '+raw);const norm=raw.replace(/\s+/g,' ').toLowerCase();if(task.commands.some(c=>c.toLowerCase()===norm)){incidentLines.push(task.output);incidentStep++;if(incidentStep===s.tasks.length){let p=incidentProgress();p[incidentIndex]=true;try{localStorage.setItem('cyber-incident-progress-v1',JSON.stringify(p))}catch{}logActivity('incident','Web障害演習：'+s.title+' をクリア');incidentLines.push('MISSION CLEAR / '+task.why)}else incidentLines.push('✓ '+task.why+'\n次の調査に進んでください。');navigate('incident')}else{incidentLines.push('コマンドを確認してください。ヒントを開いて試してみよう。');$('incidentOutput').textContent=incidentLines.join('\n');$('incidentInput').value='';$('incidentInput').focus()}}}

function init(){applyTheme();const nav=$('nav');nav.innerHTML=NAV.map(([id,icon,title])=>`<button class="nav-btn" data-page="${id}"><span class="nav-icon">${icon}</span><span>${title}</span></button>`).join('');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>{if(b.dataset.page==='infra'||b.dataset.page==='program')topicIndex=0;navigate(b.dataset.page)});$('menuToggle').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');const clock=()=>{$('clock').textContent=new Date().toLocaleString('ja-JP',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})};clock();setInterval(clock,30000);navigate('home')}
